using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class MilitaryEconomyTests
{
    static readonly EntityId Site=new("site:castle");
    internal static WorldSession Start(string person="person:nobunaga",ulong seed=1,bool armies=false)=>new(NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],person,seed,NewGameWorld.CompactPersonalAuthority,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,worldArmyPolicy:armies?NpcArmies.CompactCombatPolicy:null,economyPolicy:MilitaryEconomy.Policy));
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
    static void Advance(WorldSession s,long at){while(s.Seconds<at){long old=s.Seconds;s.SetPaused(false);s.AdvanceTo(at,100000);Assert.True(s.Seconds>old);}}
    static void OpenAll(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())s.Open(s.PlayerControl,m.Id,s.Revision);}
    static void Send(WorldSession s,NewMilitaryAction a,long n=0){var w=s.DiagnosticSnapshot();Good(s.DecideNewMilitary(new NewMilitaryInput(new("request:mil-econ/"+s.Revision+"/"+a),a,n){AuthorityPolicy=a==NewMilitaryAction.Request?NewGameMilitary.AuthorityContract:null,LedgerPolicy=a==NewMilitaryAction.Request?NewGameMilitary.LedgerIdentityContract:null,FromLedger=a==NewMilitaryAction.Request?NewGameMilitary.SourceForCurrentHouse(w):null,CycleContract=a==NewMilitaryAction.Request?NewGameMilitary.CycleForCurrentHouse(w):null},s.PlayerControl,s.Revision));}
    static void Permit(WorldSession s){Send(s,NewMilitaryAction.Request);Advance(s,s.Seconds+2);OpenAll(s);Send(s,NewMilitaryAction.Accept);Advance(s,s.Seconds+2);OpenAll(s);Send(s,NewMilitaryAction.Pickup);}
    static CommandResult Rice(WorldSession s,long kg,bool returning=false,string? id=null,EntityId? depot=null)=>s.ManageMilitaryRice(new(new(id??"request:military-rice-test/"+s.Revision),depot??NewGameMilitary.DepotFor(s.DiagnosticSnapshot()),kg,returning),s.PlayerControl,s.Revision);
    static void Finish(WorldSession s){if(NewGameMilitary.Deployed(s.DiagnosticSnapshot()))Send(s,NewMilitaryAction.Enter);long carry=NewGameMilitary.View(s.DiagnosticSnapshot()).Carry;if(carry>0)Send(s,NewMilitaryAction.Unload,carry);Send(s,NewMilitaryAction.Report);Send(s,NewMilitaryAction.Return);Advance(s,s.Seconds+3);OpenAll(s);}
    [Fact]public void ExistingGarrisonUsesSupportWorkersAndStartsWithNoFreeGrain(){var s=Start();Permit(s);var w=s.DiagnosticSnapshot();Assert.Equal(100,w.Units.Sum(u=>u.Soldiers));Assert.Equal(0,w.ResourceLots.Single(l=>l.Id==NewGameMilitary.DepotFor(w)).Quantity);Assert.Equal(0,w.ResourceLots.Single(l=>l.Id==NewGameMilitary.DepotFor(w)).InitialQuantity);Assert.Equal(200,s.CommunityEconomyView()!.Accounts.Population);Assert.Equal(80,s.CommunityEconomyView()!.Accounts.Workforce);Assert.Equal(20,s.CommunityEconomyView()!.Accounts.MilitaryWorkers);Assert.Equal(3000,s.CommunityEconomyView()!.Accounts.HouseRice);}
    [Fact]public void RealRiceFundsCarryConsumptionAndPreservedFractionalSurplus(){var s=Start();Permit(s);Good(Rice(s,60));Assert.Equal(2940,s.CommunityEconomyView()!.Accounts.HouseRice);Send(s,NewMilitaryAction.Load,60*MilitaryEconomy.PersonSecondsPerKg);Send(s,NewMilitaryAction.Deploy);Advance(s,s.Seconds+60);Send(s,NewMilitaryAction.Enter);Send(s,NewMilitaryAction.Unload,NewGameMilitary.View(s.DiagnosticSnapshot()).Carry);Assert.Equal(60*MilitaryEconomy.PersonSecondsPerKg-6000,s.MilitaryEconomyView()!.DepotPersonSeconds);Good(Rice(s,59,true));Assert.Equal(2999,s.CommunityEconomyView()!.Accounts.HouseRice);Assert.Equal(MilitaryEconomy.PersonSecondsPerKg-6000,s.MilitaryEconomyView()!.DepotPersonSeconds);Assert.Equal(ResultCode.NotAvailable,Rice(s,1,true).Code);Finish(s);Assert.Equal(100,s.CommunityEconomyView()!.Accounts.Workforce);Assert.Equal(0,s.CommunityEconomyView()!.Accounts.MilitaryWorkers);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void CurrentSupportReducesWorkshopOutput(){var s=Start();Permit(s);Advance(s,31*86400);var p=s.DiagnosticSnapshot().Materials!.Months.Single(m=>m.Site==Site);Assert.Equal(16,p.WoodMade);Assert.Equal(1,p.WeaponsMade);Assert.Equal(13,p.Wages);}
    [Fact]public void LegacyV11BytesKeepTheirSeparatePrototypeStocks(){var store=new NewCampaignStore(Path.Combine(Path.GetTempPath(),"mil-econ-old-"+Guid.NewGuid().ToString("N")));var p=store.New(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],"person:nobunaga",1,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,NewGameNpcRoutine.Policy,LocalInspectionFindings.Policy,WorkFollowup.Policy,null,VoyageExpense.Standard,NpcArmies.CompactCombatPolicy,HouseFreightReceiving.Policy,PersonalCompanions.RetainerReleasePolicy,TruceNegotiations.Policy,PrivateInformation.Policy,PrivateStanddown.Policy);var s=new WorldSession(NewCampaignStore.Build(store.Read(p.Instance)));var raw=ContractJson.Write(s.DiagnosticSnapshot());Assert.DoesNotContain("\"MilitaryEconomy\"",System.Text.Encoding.UTF8.GetString(raw));Assert.DoesNotContain("\"MilitaryWorkers\"",System.Text.Encoding.UTF8.GetString(raw));Assert.Equal(raw,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(raw)).DiagnosticSnapshot()));Assert.Null(s.MilitaryEconomyView());}

    static long Day(int y,int m,int d)=>(new DateOnly(y,m,d).DayNumber-new DateOnly(1560,1,1).DayNumber)*86400L;
    static WorldSession WithWorker(bool playerHead){var worker=NewGameWorldTests.Officer("created:mil-econ-worker",StartTemplate.Retainer,"site:castle",lord:"person:nobunaga");var setup=NewGameWorldTests.Setup([worker]);return new(NewGameWorld.Create(setup.World,setup.Registered,playerHead?"person:nobunaga":worker.Id,1,NewGameWorld.CompactPersonalAuthority,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,worldArmyPolicy:NpcArmies.CompactCombatPolicy,economyPolicy:MilitaryEconomy.Policy));}
    static WorldSession NpcRaised(){var w=Start("person:shingen",armies:true).DiagnosticSnapshot();w.CommitSequence++;NpcArmies.Muster(w,new("decision:mil-econ-npc"),new("person:nobunaga"),new("org:oda"));return new(w);}
    [Theory][InlineData(0)][InlineData(-1)][InlineData(1001)][InlineData(601)]public void InvalidOrOvercapacityRiceAllocationIsAtomic(long kg){var s=Start();Permit(s);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Rice(s,kg).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void WarehouseCannotLoadFoodBeforeRealAllocation(){var s=Start();Permit(s);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(new(new("request:load-no-origin"),NewMilitaryAction.Load,144000),s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void PermissionWithoutPickupCannotSpendHouseRice(){var s=Start();Send(s,NewMilitaryAction.Request);Advance(s,2);OpenAll(s);Send(s,NewMilitaryAction.Accept);Advance(s,4);OpenAll(s);Assert.Equal(ResultCode.NotAvailable,Rice(s,1).Code);Assert.Equal(100,s.CommunityEconomyView()!.Accounts.Workforce);}
    [Fact]public void ForeignDepotOrNpcImpersonationCannotMoveRice(){var s=Start();Permit(s);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Rice(s,1,depot:new("lot:foreign-military")).Code);Assert.Equal(ResultCode.NotAvailable,s.ManageMilitaryRice(new(new("request:fake-npc-rice"),NewGameMilitary.DepotFor(s.DiagnosticSnapshot()),120,Muster:new("decision:fake-muster")),s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void ArmyAndConstructionShareWorkersWithoutGeneratingPopulation(){var s=Start();Good(s.ConsultVillage(new(new("request:mil-water-propose"),VillageAction.ProposeWater,Site,Amount:200),s.PlayerControl,s.Revision));var q=s.DiagnosticSnapshot().Villages!.Proposals.Single().Id;Good(s.ConsultVillage(new(new("request:mil-water-confirm"),VillageAction.Confirm,Site,q),s.PlayerControl,s.Revision));Good(s.ConsultVillage(new(new("request:mil-water-start"),VillageAction.Deliver,Site,q,200),s.PlayerControl,s.Revision));Permit(s);var a=s.CommunityEconomyView()!.Accounts;Assert.Equal(80,a.Workforce);Assert.Equal(20,a.Reserved);Assert.Equal(60,a.Workforce-a.Reserved);Assert.Equal(200,a.Population);Advance(s,7*86400);Assert.Equal(80,s.CommunityEconomyView()!.Accounts.Workforce);Assert.Equal(0,s.CommunityEconomyView()!.Accounts.Reserved);}
    [Fact]public void ProtectedPreparedSalaryCannotBeTransferredToMilitaryWarehouse(){var s=WithWorker(true);var worker=new EntityId("created:mil-econ-worker");Good(s.ManageSalary(new(new("request:mil-salary"),SalaryAction.Propose,worker,Site,Amount:200),s.PlayerControl,s.Revision));var q=s.DiagnosticSnapshot().Salary!.Quotes.Single().Id;Good(s.ManageSalary(new(new("request:mil-salary-confirm"),SalaryAction.Confirm,worker,Site,q),s.PlayerControl,s.Revision));Advance(s,Day(1560,4,1));Good(s.ManageSalary(new(new("request:mil-salary-prepare"),SalaryAction.Prepare,worker,Site,q,600),s.PlayerControl,s.Revision));Good(s.ManageCommunity(new(new("request:mil-before-protected-relief"),Site,EconomyAction.RelieveVillage,2400),s.PlayerControl,s.Revision));Permit(s);Assert.Equal(600,s.CommunityEconomyView()!.Accounts.HouseRice);Assert.Equal(0,s.MilitaryEconomyView()!.HouseFreeKg);var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Rice(s,1).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void RepeatedStaleAndConflictingAllocationsCannotDuplicateGrain(){var s=Start();Permit(s);long rev=s.Revision;Good(Rice(s,60,id:"request:rice-once"));Assert.Equal(ResultCode.AlreadyAccepted,Rice(s,60,id:"request:rice-once").Code);Assert.Equal(ResultCode.IdPayloadConflict,Rice(s,61,id:"request:rice-once").Code);Assert.Equal(ResultCode.StateChanged,s.ManageMilitaryRice(new(new("request:stale-rice"),NewGameMilitary.DepotFor(s.DiagnosticSnapshot()),1),s.PlayerControl,rev).Code);Assert.Equal(2940,s.CommunityEconomyView()!.Accounts.HouseRice);}
    [Fact]public void FieldDeploymentRejectsRemoteHouseAndWarehouseHandover(){var s=Start();Permit(s);Good(Rice(s,60));Send(s,NewMilitaryAction.Load,60*MilitaryEconomy.PersonSecondsPerKg);Send(s,NewMilitaryAction.Deploy);Assert.Null(s.MilitaryEconomyView());Assert.Equal(ResultCode.NotAvailable,Rice(s,1).Code);Assert.Equal(ResultCode.NotAvailable,Rice(s,1,true).Code);}
    [Fact]public void ReturnRequestDoesNotReleaseSupportBeforeActualReturn(){var s=Start();Permit(s);Send(s,NewMilitaryAction.Return);Assert.Equal(20,s.CommunityEconomyView()!.Accounts.MilitaryWorkers);Advance(s,s.Seconds+2);Assert.Equal(20,s.CommunityEconomyView()!.Accounts.MilitaryWorkers);Send(s,NewMilitaryAction.Report);Advance(s,s.Seconds+3);OpenAll(s);Assert.Equal(0,s.CommunityEconomyView()!.Accounts.MilitaryWorkers);}
    [Fact]public void PersonalRetreatDoesNotReleaseTroopSupportOrWarehouseRice(){var s=Start();Permit(s);Good(Rice(s,60));Send(s,NewMilitaryAction.Load,60*MilitaryEconomy.PersonSecondsPerKg);Send(s,NewMilitaryAction.Deploy);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);Advance(s,s.Seconds+2);Assert.True(NewGameMilitary.Detached(s.DiagnosticSnapshot()));Assert.Equal(20,MilitaryEconomy.LaborAt(s.DiagnosticSnapshot(),Site,s.Seconds,s.Revision+1));Assert.Equal(80,s.DiagnosticSnapshot().Communities!.Accounts.Single(a=>a.Site==Site).Workforce);Assert.Equal(ResultCode.NotAvailable,Rice(s,1,true).Code);}
    [Fact]public void SeasonalLossRemainsAfterReturnJustBeforeHarvest(){var s=Start();Permit(s);Advance(s,Day(1560,9,30));Finish(s);Assert.Equal(100,s.CommunityEconomyView()!.Accounts.Workforce);Advance(s,Day(1560,10,1));var control=Start();Advance(control,Day(1560,10,1));long baseline=control.CommunityEconomyView()!.Accounts.Harvested;Assert.InRange(s.CommunityEconomyView()!.Accounts.Harvested*1000/baseline,800,805);Assert.Equal(0,s.CommunityEconomyView()!.Accounts.MilitaryWorkers);}
    [Fact]public void SupportHasNoEffectBeforeActualPickup(){var s=Start();Send(s,NewMilitaryAction.Request);Advance(s,2);OpenAll(s);Send(s,NewMilitaryAction.Accept);Advance(s,4);OpenAll(s);Assert.Equal(0,s.CommunityEconomyView()!.Accounts.MilitaryWorkers);Advance(s,31*86400);Assert.Equal(20,s.DiagnosticSnapshot().Materials!.Months.Single(m=>m.Site==Site).WoodMade);}
    [Fact]public void NpcUsesOwnLocalRiceAndReturnsAllUnusedPreparation(){var s=NpcRaised();var w=s.DiagnosticSnapshot();var depot=NewGameMilitary.LedgerIdentity(new("org:oda"),Site).Depot;Assert.Equal(2880,w.Communities!.Accounts.Single(a=>a.Site==Site).HouseRice);Assert.Equal(80,w.Communities.Accounts.Single(a=>a.Site==Site).Workforce);Assert.Equal(120*MilitaryEconomy.PersonSecondsPerKg,w.ResourceLots.Sum(l=>l.Kind=="rice"?l.Quantity:0));Assert.Equal(0,w.ResourceLots.Single(l=>l.Id==depot).InitialQuantity);Assert.Equal(1000,NewGameWork.Balance(w,new("person:nobunaga")));w.CommitSequence++;NpcArmies.Return(w,new("decision:mil-econ-npc"));var restored=new WorldSession(w);Assert.Equal(3000,restored.DiagnosticSnapshot().Communities!.Accounts.Single(a=>a.Site==Site).HouseRice);Assert.Equal(100,restored.DiagnosticSnapshot().Communities!.Accounts.Single(a=>a.Site==Site).Workforce);Assert.Equal(0,restored.DiagnosticSnapshot().ResourceLots.Where(l=>l.Kind=="rice").Sum(l=>l.Quantity));}
    [Fact]public void NpcCannotMusterWithoutRiceAndCanProceedAfterActualLevy(){var s=WithWorker(false);void Grant(){Good(s.ManageStewardship(new(new("request:mil-admin/"+s.Revision),StewardAction.Assign,Site,new("person:nobunaga"),Days:29,ReturnAddress:Site),s.PlayerControl,s.Revision));}Grant();for(int month=1;month<=6;month++){long at=Day(1560,month,1);while(s.DiagnosticSnapshot().Stewardship!.Grants.Last().Until<=at){Advance(s,s.DiagnosticSnapshot().Stewardship!.Grants.Last().Until);Grant();}Advance(s,at);Good(s.ManageStewardship(new(new("request:mil-relief/"+s.Revision),StewardAction.Operate,Site,Grant:s.DiagnosticSnapshot().Stewardship!.Grants.Last().Id,Operation:EconomyAction.RelieveVillage,Amount:500),s.PlayerControl,s.Revision));}Assert.Equal(0,s.DiagnosticSnapshot().Communities!.Accounts.Single(a=>a.Site==Site).HouseRice);var w=s.DiagnosticSnapshot();w.CommitSequence++;var before=ContractJson.Write(w);Assert.Throws<InvalidDataException>(()=>NpcArmies.Muster(w,new("decision:no-npc-grain"),new("person:nobunaga"),new("org:oda")));Assert.Equal(before,ContractJson.Write(w));long taxAt=Day(1560,10,1);while(s.DiagnosticSnapshot().Stewardship!.Grants.Last().Until<=taxAt){Advance(s,s.DiagnosticSnapshot().Stewardship!.Grants.Last().Until);Grant();}Advance(s,taxAt);Good(s.ManageStewardship(new(new("request:mil-tax-first"),StewardAction.Operate,Site,Grant:s.DiagnosticSnapshot().Stewardship!.Grants.Last().Id,Operation:EconomyAction.CollectLevy,Amount:100),s.PlayerControl,s.Revision));w=s.DiagnosticSnapshot();w.CommitSequence++;Assert.Throws<InvalidDataException>(()=>NpcArmies.Muster(w,new("decision:still-not-enough"),new("person:nobunaga"),new("org:oda")));Good(s.ManageStewardship(new(new("request:mil-tax-second"),StewardAction.Operate,Site,Grant:s.DiagnosticSnapshot().Stewardship!.Grants.Last().Id,Operation:EconomyAction.CollectLevy,Amount:20),s.PlayerControl,s.Revision));w=s.DiagnosticSnapshot();w.CommitSequence++;NpcArmies.Muster(w,new("decision:funded-after-levy"),new("person:nobunaga"),new("org:oda"));var actual=new WorldSession(w);Assert.Equal(0,actual.DiagnosticSnapshot().Communities!.Accounts.Single(a=>a.Site==Site).HouseRice);Assert.Equal(120*MilitaryEconomy.PersonSecondsPerKg,actual.DiagnosticSnapshot().ResourceLots.Where(l=>l.Kind=="rice").Sum(l=>l.Quantity));}
    [Fact]public void NpcMarchKeepsSupportAndCannotRefundAtDistance(){var s=NpcRaised();var id=new EntityId("decision:mil-econ-npc");Good(s.Submit(NpcArmies.Move(s.DiagnosticSnapshot(),id,"request:mil-npc-march","fork"),s.Revision));Advance(s,2);var w=s.DiagnosticSnapshot();Assert.Equal(20,w.Communities!.Accounts.Single(a=>a.Site==Site).MilitaryWorkers);Assert.Equal(NewGameMilitary.Capacity-100,w.ResourceLots.Single(l=>l.Kind=="rice"&&l.MobileHolder==new EntityId("person:nobunaga")).Quantity);w.CommitSequence++;Assert.Throws<InvalidDataException>(()=>NpcArmies.Return(w,id));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]public void ForgedFundingOwnershipSupportOrRationStockCannotLoad(int part){var s=Start();Permit(s);Good(Rice(s,60));var w=s.DiagnosticSnapshot();if(part==0)w.MilitaryEconomy=w.MilitaryEconomy! with{Entries=[..w.MilitaryEconomy.Entries.Select(e=>e with{Input=e.Input with{RiceKg=999}})]};if(part==1)w.MilitaryEconomy=w.MilitaryEconomy! with{Entries=[..w.MilitaryEconomy.Entries.Select(e=>e with{Owner=new("org:takeda")})]};if(part==2)w.Communities=w.Communities! with{Accounts=[..w.Communities.Accounts.Select(a=>a.Site==Site?a with{MilitaryWorkers=0,Workforce=100}:a)]};if(part==3)w.ResourceLots=[..w.ResourceLots.Select(l=>l.Id==NewGameMilitary.DepotFor(w)?l with{Quantity=l.Quantity+1}:l)];Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void ProfileStartsWithExplicitV12AndKeepsPreviousModules(){var store=new NewCampaignStore(Path.Combine(Path.GetTempPath(),"mil-econ-profile-"+Guid.NewGuid().ToString("N")));var p=store.New(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],"person:nobunaga",1,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,NewGameNpcRoutine.Policy,LocalInspectionFindings.Policy,WorkFollowup.Policy,null,VoyageExpense.Standard,NpcArmies.CompactCombatPolicy,MilitaryEconomy.Policy,PersonalCompanions.RetainerReleasePolicy,TruceNegotiations.Policy,PrivateInformation.Policy,PrivateStanddown.Policy);var s=new WorldSession(NewCampaignStore.Build(store.Read(p.Instance)));Assert.True(MilitaryEconomy.Enabled(s.DiagnosticSnapshot()));Assert.True(HouseFreightReceiving.Enabled(s.DiagnosticSnapshot()));Assert.Equal(30,s.DiagnosticSnapshot().Communities!.Accounts.Length);Permit(s);Good(Rice(s,60));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)][InlineData(6)][InlineData(7)][InlineData(8)][InlineData(9)]public void ActualGenerationRecoveryKeepsCivilLaborRiceCarryAndReturn(int phase){var a=phase>=8?NpcRaised():Start();if(phase<8){Permit(a);if(phase>=1)Good(Rice(a,60));if(phase>=2)Send(a,NewMilitaryAction.Load,60*MilitaryEconomy.PersonSecondsPerKg);if(phase>=3){Send(a,NewMilitaryAction.Deploy);Advance(a,a.Seconds+2);}if(phase==4){Send(a,NewMilitaryAction.Handoff);Send(a,NewMilitaryAction.Withdraw);Advance(a,a.Seconds+2);}if(phase is 5 or 6 or 7){Send(a,NewMilitaryAction.Enter);Send(a,NewMilitaryAction.Unload,NewGameMilitary.View(a.DiagnosticSnapshot()).Carry);if(phase>=6)Good(Rice(a,59,true));if(phase==7)Finish(a);}}else if(phase==9){var w0=a.DiagnosticSnapshot();w0.CommitSequence++;NpcArmies.Return(w0,new("decision:mil-econ-npc"));a=new(w0);}a.SetPaused(true);var w=a.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"military-econ-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(a,"military-econ",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("military-econ"),host.Current,host.Current.Revision));var b=host.Current;Assert.Equal(ContractJson.Write(a.MilitaryEconomyView()),ContractJson.Write(b.MilitaryEconomyView()));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,"mil-econ-"+phase+".before.json"),ContractJson.Write(a.DiagnosticSnapshot()));File.WriteAllBytes(Path.Combine(dir,"mil-econ-"+phase+".restored.json"),ContractJson.Write(b.DiagnosticSnapshot()));}foreach(var s in new[]{a,b}){Advance(s,s.Seconds+2);if(phase==0)Good(Rice(s,1));if(phase is 1 or 2)Finish(s);if(phase==3){Send(s,NewMilitaryAction.Enter);Finish(s);}if(phase is 5 or 6)Finish(s);}Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));}

    [Fact]public void ExistingUserIdCannotPreventNpcRiceFunding(){var s=Start("person:shingen",armies:true);var muster=new EntityId("decision:mil-econ-nonce");string claimed="request:military-rice/fund/"+ContractJson.Hash(System.Text.Encoding.UTF8.GetBytes(muster.Value));Good(s.TradeRice(new(new(claimed),TradeAction.Quote,new("site:kofu"),Destination:Site,Amount:1){Commodity="wood"},s.PlayerControl,s.Revision));var w=s.DiagnosticSnapshot();w.CommitSequence++;NpcArmies.Muster(w,muster,new("person:nobunaga"),new("org:oda"));var actual=new WorldSession(w);Assert.Equal(claimed+"/n1",actual.DiagnosticSnapshot().MilitaryEconomy!.Entries.Single().Input.Id.Value);}
}
